def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header (str): The value of the Range header (e.g., "bytes=0-499").
        size (int): The total size of the resource in bytes.

    Returns:
        list: A list of (start, end) inclusive byte offsets, or None if unsatisfiable.
    """
    if not header.startswith("bytes="):
        return None

    ranges_str = header[6:]  # Remove "bytes="
    if not ranges_str:
        return None

    ranges = []
    parts = ranges_str.split(",")

    for part in parts:
        part = part.strip()
        if not part:
            continue

        if "-" not in part:
            return None

        suffix_length = None
        start_str, end_str = part.split("-", 1)

        if start_str == "":
            # Suffix range: e.g., "-500"
            try:
                suffix_length = int(end_str)
            except ValueError:
                return None

            if suffix_length <= 0:
                return None

            if suffix_length > size:
                # Suffix length larger than resource yields the whole resource
                start = 0
                end = size - 1
            else:
                start = size - suffix_length
                end = size - 1

            ranges.append((start, end))

        elif end_str == "":
            # Prefix range: e.g., "500-"
            try:
                start = int(start_str)
            except ValueError:
                return None

            if start < 0 or start >= size:
                # Start at or past size is unsatisfiable
                continue

            end = size - 1
            ranges.append((start, end))

        else:
            # Normal range: e.g., "0-499"
            try:
                start = int(start_str)
                end = int(end_str)
            except ValueError:
                return None

            if start < 0 or end < start:
                return None

            # Clamp end if past the last byte
            if end >= size:
                end = size - 1

            # If start is at or past size, this specific range is unsatisfiable
            if start >= size:
                continue

            ranges.append((start, end))

    if not ranges:
        return None

    return ranges
```

