module.exports = function pLimit(n) {
  if (n < 1) {
    return async function(fn) {
      throw new Error('Concurrency limit must be at least 1');
    };
  }

  let activeCount = 0;
  let queue = [];
  let isProcessing = false;

  return async function(fn) {
    return new Promise((resolve, reject) => {
      const job = async () => {
        try {
          const result = await fn();
          resolve(result);
        } catch (error) {
          reject(error);
        } finally {
          activeCount--;
          if (queue.length > 0) {
            const next = queue.shift();
            next();
          }
        }
      };

      if (activeCount < n) {
        activeCount++;
        job();
      } else {
        queue.push(job);
      }
    });
  };
};

